output_text:
[
  {
    "id": "no_cart_single_file",
    "text": "Shopping carts are not allowed in single-file shelf aisles.",
    "abstraction": {
      "state_properties": {
        "single_file_aisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "single_file_aisle"
        ]
      }
    }
  },
  {
    "id": "no_cart_motion_single_file",
    "text": "A shopper must not push a cart while moving inside a single-file shelf aisle.",
    "abstraction": {
      "state_properties": {
        "single_file_aisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "MOVE",
          "single_file_aisle"
        ]
      }
    }
  },
  {
    "id": "no_enter_narrow_with_cart",
    "text": "A shopper must not enter a single-file shelf aisle while holding a cart.",
    "abstraction": {
      "state_properties": {
        "single_file_aisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "enter_single_file_with_cart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": "single_file_aisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enter_single_file_with_cart"
    }
  },
  {
    "id": "park_at_upper_lane_mouth",
    "text": "On arriving with a cart at the mouth of an upper single-file shelf lane, the shopper must park the cart before proceeding.",
    "abstraction": {
      "state_properties": {
        "upper_single_file_lane_mouth": {
          "and": [
            {
              "or": [
                "at(3,3)",
                "at(6,3)"
              ]
            },
            {
              "ge": [
                "freeWidthH",
                6
              ]
            }
          ]
        },
        "cart_parked": {
          "not": "hasCart"
        }
      },
      "events": {
        "arrive_at_upper_lane_mouth_with_cart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": "upper_single_file_lane_mouth"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "arrive_at_upper_lane_mouth_with_cart",
      "discharge": "cart_parked"
    }
  },
  {
    "id": "canyon_pickups_on_foot",
    "text": "Items located in narrow shelf canyons must not be collected while holding a cart.",
    "abstraction": {
      "state_properties": {
        "shelf_canyon": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "INTERACT",
          "shelf_canyon"
        ]
      }
    }
  },
  {
    "id": "reclaim_after_parking",
    "text": "Whenever a shopper parks a cart, they must reclaim a cart before leaving the store.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "park_cart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "park_cart",
      "discharge": "hasCart"
    }
  },
  {
    "id": "reclaim_after_onfoot_canyon_item",
    "text": "After collecting an item on foot from a narrow shelf canyon, the shopper must return to and reclaim the cart.",
    "abstraction": {
      "state_properties": {
        "shelf_canyon": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "onfoot_canyon_pickup": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT",
              "shelf_canyon"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "onfoot_canyon_pickup",
      "discharge": "hasCart"
    }
  },
  {
    "id": "side_shelf_with_cart",
    "text": "Items reachable from a wide aisle side shelf should be collected with the cart rather than by walking in without it.",
    "abstraction": {
      "state_properties": {
        "wide_side_shelf_access": {
          "and": [
            "adjShelf",
            {
              "or": [
                "shelfN",
                "shelfS"
              ]
            },
            {
              "ge": [
                "freeWidthH",
                6
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          {
            "not": "hasCart"
          },
          "INTERACT",
          "wide_side_shelf_access"
        ]
      }
    }
  }
]
